/**
 * The engine's single source of "now".
 *
 * A {@link Clock} returns the current time as an ISO-8601 string. Each
 * verb-driven operation takes ONE reading and threads it everywhere —
 * `$now` in filters, the `now` op-source, every history `at` stamp,
 * `completedAt`, `enteredAt`, `lastChangedAt` — so an eval pass agrees on
 * the time and a frozen clock produces a deterministic instance.
 *
 * A clock is injected ONCE, never per call: production omits it entirely
 * (defaults to {@link wallClock}); deterministic harnesses pass
 * `createEngine({ clock })`, and tests use `@sanity/workflow-engine-test`'s
 * `setNow` / `advance` (the bench wraps the same seam). It is deliberately
 * NOT a field on the public per-verb `*Args` — the raw `workflow.*` verbs
 * accept it only through the {@link Clocked} composition seam, so prod code
 * can't trivially override engine time by accident.
 *
 * `drainEffects` and `sweepStaleClaims` read the same engine clock for
 * their claim / lease-expiry stamps, so lease timing is deterministic
 * under a pinned clock too.
 */
export declare type Clock = () => string;

/**
 * Optional clock-injection field on the raw `workflow.*` verbs. It is
 * exported because those verbs expose this composition helper in their
 * public signatures, but production normally injects a clock once via
 * `createEngine({ clock })`, and the test bench controls it through
 * `setNow` / `advance`. The documented `*Args` interfaces omit `clock`
 * because it is infrastructure context, not an everyday per-call option.
 */
export declare type Clocked<T> = T & {
  clock?: Clock;
};

export declare interface CommitEffectOpsArgs extends DedupableOperationArgs {
  /** The `_key` of the pending effect being reported on. */
  effectKey: string;
  /**
   * Required here, unlike the other dedupable verbs: the engine cannot
   * assume a supplied field op is idempotent, so every mid-dispatch report
   * must be retry-safe. (The runtime check remains for untyped callers.)
   */
  idempotencyKey: string;
  /**
   * The exact-claim identity handed to the reporting dispatch. The commit
   * re-reads the instance and rejects (writing nothing) unless the entry's
   * live claim carries this token unexpired — so an expired, released, or
   * superseded handler cannot update state. A successful commit renews the
   * claim's lease.
   */
  claimToken: string;
  /**
   * Mid-dispatch field state, `field.*` ops only — validated and applied
   * exactly like completion ops (same applier, same target resolution
   * against the current open stage, workflow-/stage-scope only, never
   * `status.set`). Must be non-empty. Completion ops remain the final
   * atomic result committed when the handler returns; these are separately
   * committed and observable before it.
   */
  ops: FieldOp[];
  /** Lease duration the successful commit renews the claim to — the
   *  drain's `effects.leaseMs`. Default `DEFAULT_EFFECT_LEASE_MS` (5 min). */
  leaseMs?: number;
}

export declare interface CommitOpsRequest {
  ops: FieldOp[];
  idempotencyKey: string;
}

