/**
 * Translate one authored guard into the temporary documents that preview its
 * eventual Content Lake enforcement.
 * Content edits target draft ids, instance updates keep the instance id, and
 * publish or unpublish targets published ids using the Lake operations those
 * lifecycle writes perform. A mixed guard emits one document per id space so
 * its action and id facets never form an unintended cross-product.
 */
export declare function compileGuards(
  args: CompileGuardsArgs,
): [MutationGuardDoc, ...MutationGuardDoc[]];

export declare interface CompileGuardsArgs extends MutationGuardBody {
  id: string;
}

/**
 * Completion is FIRST-WRITER-WINS: reporting on an entry that already
 * settled throws `EffectNotFoundError`, whose `settled` field says how it
 * settled — another party's completion (a lease takeover, a manual
 * recovery), or an abort cancelling the entry before dispatch. A completer
 * on a retrying transport (webhook redelivery, queue, cron) should pass
 * {@link DedupableOperationArgs.idempotencyKey} — its own lost-response
 * retries then replay as `changed: false` instead of throwing.
 */
export declare interface CompleteEffectArgs extends DedupableOperationArgs {
  /** The `_key` of the pending effect being reported on. */
  effectKey: string;
  status: EffectCompletionStatus;
  /**
   * Named values produced by the effect — recorded on the run's
   * `effectHistory` row and read downstream as
   * `$effects['<effect name>'].<output>` (the latest completed run per
   * effect name wins). Validated against the effect's declared `outputs`
   * allowlist; each value may be any JSON.
   */
  outputs?: Record<string, unknown>;
  /**
   * The state half of the effect: `field.*` ops to apply in the completion
   * commit, computed from the effect's real result (e.g. a `field.set` of a
   * created doc's ref, or the screened outcome an activity/stage gate then reads).
   * Run through the same op applier as an action's field ops — a target must
   * resolve in the current open stage and its value must match the field's kind;
   * workflow- and stage-scope targets only. Deliberately NOT `status.set`: an
   * effect is outside the activity's awaiting, so it reports its result as field
   * state and lets the gate decide the activity/stage outcome — it never flips an
   * activity status itself (same boundary a transition draws). Only valid with
   * `status: 'done'` (a failed completion carries no ops). Not actor-gated.
   */
  ops?: FieldOp[];
  detail?: string;
  error?: {
    message: string;
    stack?: string;
  };
  durationMs?: number;
}

