/**
 * Thrown when one automatic cascade hop loses every optimistic-locking
 * attempt. An earlier verb commit may already have landed; invoke `tick`
 * after re-reading the instance to resume convergence when contention subsides.
 */
export declare class ConcurrentCascadeError extends WorkflowError<"concurrent-cascade"> {
  readonly instanceId: string;
  readonly attempts: number;
  constructor(args: { instanceId: string; attempts: number });
}

/** {@link ConcurrentCompleteEffectError}'s mid-dispatch sibling: a
 *  `commitEffectOps` commit lost every optimistic-locking attempt. Nothing
 *  was written; the report may be retried under the same idempotency key. */
export declare class ConcurrentCommitEffectOpsError extends WorkflowError<"concurrent-commit-effect-ops"> {
  readonly instanceId: string;
  readonly effectKey: string;
  readonly attempts: number;
  constructor(args: {
    instanceId: string;
    effectKey: string;
    attempts: number;
  });
}

/**
 * Completion twin of {@link ConcurrentFireActionError}: a `completeEffect`
 * commit lost the optimistic-locking race on every attempt. Same contract —
 * nothing committed on the final try, so the pending entry (and its claim)
 * is untouched: the completion can be retried, and a claim whose lease
 * lapses is recovered by a later drain. The handler's reported outcome is
 * NOT applied — a caller that retries must not re-run the side effect,
 * only re-report it.
 */
export declare class ConcurrentCompleteEffectError extends WorkflowError<"concurrent-complete-effect"> {
  readonly instanceId: string;
  readonly effectKey: string;
  readonly attempts: number;
  constructor(args: {
    instanceId: string;
    effectKey: string;
    attempts: number;
  });
}

/**
 * Edit-seam twin of {@link ConcurrentFireActionError}: an `editField` commit
 * lost the optimistic-locking race on every attempt. Same contract — re-read
 * and retry, or investigate a write storm; nothing committed on the final try.
 */
export declare class ConcurrentEditFieldError extends WorkflowError<"concurrent-edit-field"> {
  readonly instanceId: string;
  readonly target: {
    scope: FieldScope;
    field: string;
    activity?: string;
  };
  readonly attempts: number;
  constructor(args: {
    instanceId: string;
    target: {
      scope: FieldScope;
      field: string;
      activity?: string;
    };
    attempts: number;
  });
}

/**
 * Thrown when a `fireAction` commit loses the optimistic-locking race on
 * every commit attempt — each reload +
 * `ifRevisionId` retry was beaten by another writer committing first.
 * Surfacing it (rather than silently overwriting) lets the caller decide
 * whether to retry later or report a write storm; nothing was committed
 * on the final attempt.
 */
export declare class ConcurrentFireActionError extends WorkflowError<"concurrent-fire-action"> {
  readonly instanceId: string;
  readonly activity: ActivityName;
  readonly action: string;
  readonly attempts: number;
  constructor(args: {
    instanceId: string;
    activity: ActivityName;
    action: string;
    attempts: number;
  });
}

/**
 * A raw GROQ string evaluated over the rendered scope: the engine-bound
 * variables inventoried in {@link CONDITION_VARS} (each annotated with the
 * context that binds it) plus the author's nullary `predicates` as `$<name>`
 * booleans. Evaluation runs against the instance's in-memory snapshot —
 * never a `_type` scan over the lake (rejected at deploy).
 *
 * There is no `{ref, args}` wrapper: parameterized reuse is a define-time
 * TypeScript function producing a condition string (see the {@link define.groq | groq} tag).
 */
export declare type Condition = string;

/**
 * Every variable the engine binds for the RENDERED condition scope (every
 * condition site: transition `when`s, activity filters, action
 * `when`s/filters, effect bindings, `spawn` reads, where-op `where`s,
 * editability predicates, author predicates) — the deploy-time shadow check
 * ({@link RESERVED_CONDITION_VARS}) and the docs on {@link Condition} derive
 * from this list; extend it here when the engine grows a binding, never in
 * a comment elsewhere.
 *
 * Three other GROQ contexts read a definition and do NOT share this
 * inventory: cascade gates (transition/activity/cascade-action gates, which
 * must resolve identically regardless of caller — only the `'always'`-bound
 * subset carries values, {@link FILTER_SCOPE_VARS}); the start contexts
 * (`start.filter` is browse-time-pure over a candidate document,
 * {@link START_FILTER_VARS}; a start `groq` requirement binds `$fields`
 * instead, {@link START_REQUIREMENT_VARS}); and lake guard predicates, which
 * are not conditions at all — delta-mode GROQ over a mutation, binding
 * {@link GUARD_PREDICATE_VARS} instead.
 */
