export declare interface DeployDefinitionResult {
  /** The definition's `name`. */
  name: string;
  /** The deploy-assigned version this deploy created or matched. */
  version: number;
  status: "created" | "unchanged";
  /**
   * Advisory producer/consumer warnings from the effect-output lint — a
   * `$effects['<name>'].<key>` read of a key a declared effect does not produce.
   * Non-blocking: deploy still succeeds. Absent when the definition is clean.
   * See {@link lintEffectOutputs}.
   */
  warnings?: string[];
}

export declare interface DeployDefinitionsArgs<
  T extends WorkflowDefinitionInput<T> = WorkflowDefinition,
> {
  /**
   * Highest reader model verified across runtimes sharing the workflow resource. The deploy gate
   * compares this reviewed numeric literal with the submitted definitions; do not import
   * either exported reader constant, because a dependency upgrade must not change it automatically.
   */
  expectedMinReaderModel: number;
  /**
   * Resource-alias bindings for this deploy (alias name → physical resource).
   * A deploy-time abstraction ONLY: every `@<alias>:` reference in a
   * definition is expanded to its bound physical resource before the
   * deployed definition is fingerprinted and stored, and deploy fails closed
   * on an unbound alias. Aliases never exist past deploy — no stored
   * document carries one, the runtime never sees the map, and an
   * alias-shaped ref reaching a runtime boundary is rejected as malformed.
   * Omit for single-resource workflows (definitions referencing no aliases).
   */
  resourceAliases?: ResourceAliases;
  /** Authored definitions (the default — full compile-time checking) or
   *  loosely-typed fetched definition documents — the boundary parse
   *  normalizes either ({@link WorkflowDefinitionInput}). */
  definitions: T[];
}

export declare interface DeployDefinitionsResult {
  /** Per-definition outcome, ordered by the resolved deploy order (children first). */
  results: DeployDefinitionResult[];
  /**
   * Random id grouping this call's per-definition deploy telemetry events.
   * Returned so a caller reporting on the same deploy (e.g. definition
   * sharing) can carry the id the events already minted.
   */
  deployId: string;
}

/** A definition as fetched back from the lake. The document carries `_id` plus
 *  the deploy-stamped envelope the authored {@link WorkflowDefinition} never
 *  had: the assigned `version` and the content fingerprint it was minted from
 *  ({@link hashDefinitionContent}). */
export declare type DeployedDefinition = WorkflowDefinition & {
  _id: string;
  tag?: string;
  version: number;
  /** Optional: a document deployed before content-addressing has none. Every
   *  version this engine deploys carries one. */
  contentHash?: string;
  /** Engine data-model stamp (see {@link DATA_MODEL_VERSION}) — absent on
   *  documents deployed before the stamp existed (model 0). */
  modelVersion?: number;
  /** The oldest engine data model that can safely interpret this document,
   *  derived from its persisted features and the retained model-4 baseline. */
  minReaderModel?: number;
};

/**
 * GROQ listing every tag partition holding a deployed
 * {@link WORKFLOW_DEFINITION_TYPE} in the resource. The un-scoped
 * inverse of {@link tagScopeFilter}, this deliberately spans partitions.
 */
export declare function deployedTagsGroq(): string;

/**
 * Deploy every guard for a stage being entered (idempotent upsert), but only
 * while the instance is still committed to that stage. A deploy that lost the
 * race to a newer transition would otherwise re-lock a stage the instance
 * already left — a stale lock the newer transition's retract can't see. A
 * vanished instance (`undefined`) likewise no-ops: `undefined !== stageName`.
 *
 * An aborted instance also no-ops: it parks on its stage forever, so a stale
 * deploy landing after abort's retract would re-lock the subjects with no
 * remaining path to delete them. The gate is `abortedAt`, not `completedAt` —
 * a normal move *into* a terminal stage stamps `completedAt` in the same
 * persist and must still deploy that stage's guards.
 */
export declare function deployStageGuards(args: StageGuardArgs): Promise<void>;

/** Structurally what `deployDefinitions` receives, minus the definitions; carrying `resourceAliases` here keeps a diff's fingerprint matching what deploy would produce. */
export declare interface DeployTarget {
  /** Highest reader model verified across runtimes sharing this workflow resource. */
  expectedMinReaderModel: number;
  tag: string;
  workflowResource: WorkflowResource;
  resourceAliases?: ResourceAliases;
}

/** Classifies an activity from its shape: `target` marks off-system work
 *  (`manual`), the one bit action shapes alone can't otherwise show. Then:
 *  any caller-fireable action → `user`; effects or spawns → `service`;
 *  cascade-only actions → `receive`; no actions at all → `script`. */
