/**
 * The activity slice the document-derivable stuck causes read: its runtime
 * status, and the declared actions whose effects a failure is matched against.
 * Narrowed to exactly this, so one set of cause functions serves both a full
 * {@link WorkflowEvaluation} and {@link documentStuckCause}'s snapshot-derived
 * rows.
 */
declare interface DiagnosedActivity {
  status: ActivityStatus;
  activity: Pick<Activity, "name" | "actions">;
}

/** The slice of a {@link TransitionEvaluation} the classifier reads — narrowed
 *  so a hand-crafted stuck permutation doesn't have to fabricate insights. */
export declare type DiagnosedTransition = Pick<
  TransitionEvaluation,
  "transition" | "whenSatisfied" | "unevaluable"
>;

/**
 * The slice of an instance + its {@link WorkflowEvaluation} the classifier
 * reads. Narrowed so callers (and tests) can craft an exact stuck permutation
 * without standing up a full evaluation; {@link diagnoseInputFromEvaluation}
 * builds it from a real {@link WorkflowEvaluation}.
 */
export declare interface DiagnoseInput extends DocumentStuckInput {
  instance: Pick<
    WorkflowInstance,
    | "currentStage"
    | "completedAt"
    | "abortedAt"
    | "effectHistory"
    | "pendingEffects"
    | "history"
    | "subworkflows"
  >;
  activities: ActivityEvaluation[];
  transitions: DiagnosedTransition[];
  assignees: Record<string, Assignee[]>;
}

/** Narrow a full {@link WorkflowEvaluation} to the {@link DiagnoseInput} the
 *  classifier reads. */
export declare function diagnoseInputFromEvaluation(
  evaluation: WorkflowEvaluation,
): DiagnoseInput;

/**
 * Classify an instance. Terminal states win first; then the genuine stuck
 * causes (nothing advances on its own or via a normal action); then `waiting`
 * (an action is available — healthy); then `blocked` (an active activity held by
 * an unmet requirement — healthy, not yet actionable); else `progressing` (a
 * transition is already satisfied and will cascade).
 */
export declare function diagnoseInstance(input: DiagnoseInput): Diagnosis;

/** The `workflow.diagnose` result — the verdict, the structured remediations
 *  that would unstick it (empty unless `stuck`), and the evaluation it was
 *  derived from, so a consumer can render the supporting evidence (current
 *  stage activities + transitions) without a second projection. */
export declare interface DiagnoseResult {
  evaluation: WorkflowEvaluation;
  diagnosis: Diagnosis;
  remediations: SuggestedRemediation[];
}

/**
 * How an instance reads right now. `waiting` and `blocked` are both healthy,
 * not stuck. A `waiting` result says whether the activity awaits an
 * action available to this caller (`caller`), a manual action that this caller
 * cannot currently take (`manual-action`), or a cascade-fired action
 * (`automation`). How long a workflow is "allowed" to wait is workflow- and
 * team-specific, not this classifier's call. `blocked` means an active
 * activity's declared requirements aren't all met
 * yet, and flips to `waiting` once they hold (typically a sibling activity
 * completing, or content landing). Completed and aborted results include
 * `liveChildren` while detached spawned work remains active; consumers should
 * surface it prominently.
 */
export declare type Diagnosis =
  | {
      state: "progressing";
    }
  | {
      state: "waiting";
      activity: string;
      assignees: Assignee[];
      actions: string[];
      waitingFor: "automation" | "caller" | "manual-action";
    }
  | {
      state: "blocked";
      activity: string;
      requirements: string[];
      assignees: Assignee[];
    }
  | {
      state: "completed";
      at: string;
      liveChildren?: number;
    }
  | {
      state: "aborted";
      at: string;
      reason?: string;
      liveChildren?: number;
    }
  | {
      state: "stuck";
      cause: StuckCause;
    };

export declare interface DiffEntry {
  name: string;
  /** The version this deploy WOULD write, or the matched version when unchanged. */
  version: number;
  status: "create" | "unchanged";
  docId: string;
  /** The document deploy would write — including the stamped `version` and
   *  `contentHash`. */
  expected: Record<string, unknown>;
  /** The latest deployed document, system fields stripped — the prior shape to
   *  diff against. Absent when nothing is deployed yet. */
  existing?: Record<string, unknown>;
}

/**
 * Classifies `def` against the latest deployed version of its name via
 * the deploy planner — a content change is always a new version,
 * never an in-place update. `def` passes the same boundary parse deploy uses
 * ({@link parseDefinitionInput}), so diff and deploy accept and reject the
 * same input shape.
 */
export declare function diffEntry<T extends WorkflowDefinitionInput<T>>({
  def: rawDef,
  latestRaw,
  target,
}: {
  def: T;
  latestRaw: Record<string, unknown> | undefined;
  target: DeployTarget;
}): DiffEntry;

/**
 * Why an action is disabled for this actor right now — the read-side verdict.
 *
 * Verdict↔exception mapping (what `fireAction` throws when the verdict says
 * no): the `mutation-guard-denied` arm escalates to
 * {@link MutationGuardDeniedError} — the one guard-denial error, shared by
 * every verb; every other arm is thrown as {@link ActionDisabledError}
 * carrying the verdict as `reason`. The edit seam mirrors this: see
 * {@link EditDisabledReason} and {@link EditFieldDeniedError}.
 */
export declare type DisabledReason =
  | {
      /**
       * The action's condition evaluated falsy for this actor — the ONE
       * engine-side gate (advisory, like every engine check). Sugar like
       * `roles` desugared into this condition, so a role miss surfaces
       * here too. Under filter-existence semantics a consumer renders the
       * action ABSENT, never disabled.
       */
      kind: "filter-failed";
      filter: string;
      detail?: string;
    }
  | {
      /** The action is cascade-fired (`when`) — the engine's cascade is its
       *  only firing path; `fireAction` rejects it for every caller. */
      kind: "cascade-fired";
      when: string;
    }
  | {
      kind: "activity-not-active";
      status: TerminalActivityStatus;
    }
  | {
      kind: "stage-terminal";
      stage: StageName;
    }
  | {
      /**
       * A deployed mutation guard denies the instance write every action
       * commit performs. Advisory pre-flight — the engine's optimistic
       * evaluation; `denied` is the same {@link DeniedGuardRef} shape the
       * thrown {@link MutationGuardDeniedError} carries.
       */
      kind: "mutation-guard-denied";
      denied: DeniedGuardRef[];
    }
  | {
      kind: "instance-completed";
      completedAt: string;
    }
  | {
      /** The instance was hard-stopped via `abortInstance`. Aborted instances
       *  carry `completedAt` too, so this arm wins over `instance-completed`
       *  (the {@link terminalState} precedence). */
      kind: "instance-aborted";
      abortedAt: string;
    }
  | {
      /**
       * The activity's declared {@link Activity.requirements} aren't all satisfied —
       * the readiness axis. The activity is visible and the actor authorized, but
       * its own preconditions don't hold yet. `unmetRequirements` carries the
       * authored descriptors so a consumer can disable the affirmative control and say
       * which precondition is outstanding. Distinct from `filter-failed`
       * (visibility/authorization) and `mutation-guard-denied` (content-write).
       */
      kind: "requirements-unmet";
      unmetRequirements: RequirementDescriptor[];
    }
  | {
      /**
       * The actor's grants on an involved subject's resource don't allow the
       * content write the action's effects would perform there. Forecast
       * per-resource: each subject named by a `doc.ref`/`subject`/`doc.refs`/`release.ref`
       * field entry outside the workflow's own resource is checked against
       * THAT resource's ACL. Advisory like every engine verdict — the subject's
       * lake still enforces; and it degrades open: a resource whose grants
       * can't be fetched is simply not forecast.
       */
      kind: "subject-permission-denied";
      denied: SubjectPermissionDenial[];
    };

/**
 * Single combined map for callers that don't care which family the
 * key belongs to (e.g. an audit row showing any `_type`).
 */
export declare const DISPLAY: Record<string, DisplayMetadata>;

/**
 * Same idea but returns the description, or undefined when unknown.
 */
